def is_existing_project(root):
    return (root / "pyproject.toml").is_file() and (
        root / "src" / "forgecore" / "__init__.py"
    ).is_file()


def main():
    cwd = Path.cwd()
    if is_existing_project(cwd):
        root = cwd
        print("  + Detected existing ForgeCore project at " + str(root))
    elif is_existing_project(cwd / PROJECT_NAME):
        root = cwd / PROJECT_NAME
        print("  + Found ForgeCore project at " + str(root))
    else:
        root = cwd / PROJECT_NAME
        if root.exists():
            print("  ! Removing existing " + str(root))
            shutil.rmtree(root)
        root.mkdir(parents=True)
        print("  + Created " + str(root))

    for d in DIRS:
        target = root / d
        target.mkdir(parents=True, exist_ok=True)

    written = []
    for rel, b64_value in FILES.items():
        if isinstance(b64_value, tuple):
            b64 = "".join(b64_value)
        else:
            b64 = b64_value
        content = base64.b64decode(b64)
        target = root / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(content)
        written.append(rel)

    print("  + Wrote " + str(len(written)) + " source files")
    print("")

    # Now generate the PDFs locally
    print("  Generating 10 ForgeCore PDFs...")
    gen_script = root / "scripts" / "generate_documents.py"
    if gen_script.is_file():
        try:
            subprocess.run(
                [sys.executable, str(gen_script)],
                cwd=root,
                check=True,
                capture_output=True,
                text=True,
            )
            print("  + PDFs generated")
        except subprocess.CalledProcessError as exc:
            print("  ! PDF generation failed: " + str(exc))
            print("    You can retry later with: python scripts/generate_documents.py")
    else:
        print("  ! generate_documents.py not found, skipping PDF generation")

    print("")
    print("  Stage 2 setup complete!")
    print("")
    rel_root = "." if root == cwd else str(root.relative_to(cwd))
    print("  Next:")
    print("    cd " + rel_root)
    print('    pip install -e ".[ingestion]"')
    print("    pytest tests/ -v")
    print("    python scripts/ingest_documents.py")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print("  ERROR: " + str(exc), file=sys.stderr)
        sys.exit(1)
